remediationSample:
Avoid redirecting to URLs built from user input.
If this is not possible, validate the arguments using a dedicated method and declare this method as a sanitization method for the quality rule. Example of such methods:

// ----------------------------------------------------------------------------
// 1) Java sample

import jakarta.servlet.http.HttpServletResponse;
import java.sql.*;
import java.io.IOException;
import java.net.*;
import static java.sql.DriverManager.getConnection;
public class Main {
  private static final String TRUSTED_HOST = "trusted.example.com";
  public static String getUserName(int userId) throws SQLException {
    String sql = "SELECT user_name FROM app_users WHERE user_id = ?";
    try (Connection conn = getConnection("jdbc:mysql://localhost/mydb"); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery(sql)) {
      return rs.next() ? rs.getString(1) : "";
    }
  }
  public static void redirect_secure(int userId, HttpServletResponse response) throws SQLException, IOException {
    String userName = getUserName(userId);
    String safeUrl = trySanitizeRedirectUrl(userName);
    if (safeUrl == null) { response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Redirect not allowed."); return; }
    response.sendRedirect(safeUrl); // ✓ OK: redirection restricted to an allow-listed target
  }
  private static String trySanitizeRedirectUrl(String input) {
    if (input == null) return null;
    URI uri; try { uri = new URI(input); } catch (URISyntaxException e) { return null; }
    if (!uri.isAbsolute() || !TRUSTED_HOST.equalsIgnoreCase(uri.getHost())) return null;
    return uri.toString();
  }
}

// ----------------------------------------------------------------------------
// 2) C# sample

using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using System;
internal class Program : ControllerBase
{
  private const string TrustedHost = "trusted.example.com";
  private static string GetUserName(int userId)
  {
    string sql = "SELECT [UserName] FROM [AppUsers] WHERE [UserId] = @userId";
    using SqlConnection connection = new SqlConnection("connectionString");
    connection.Open();
    using SqlCommand command = new SqlCommand(sql, connection);
    command.Parameters.AddWithValue("@userId", userId);
    using SqlDataReader reader = command.ExecuteReader();
    return reader.Read() ? reader.GetString(0) : "";
  }
  private void Redirect_secure(int userId)
  {
    string userName = GetUserName(userId);
    Uri? safeUri = TrySanitizeRedirectUrl(userName);
    if (safeUri == null) return;
    Redirect(safeUri.ToString()); // ✓ OK: redirection restricted to an allow-listed target
  }
  private static Uri? TrySanitizeRedirectUrl(string? input)
  {
    if (input == null) return null;
    Uri uri; try { uri = new Uri(input, UriKind.Absolute); } catch (UriFormatException) { return null; }
    if (!string.Equals(uri.Host, TrustedHost, StringComparison.OrdinalIgnoreCase)) return null;
    return uri;
  }
}

